<?php namespace App\Filament\Pages;use Filament\Pages\Page;use Illuminate\Support\Facades\DB;
class UpbringingInsights extends Page{protected static ?string $navigationIcon='heroicon-o-chart-bar';protected static ?string $navigationLabel='Рейтинги и аналитика';protected static ?string $navigationGroup='Воспитательная работа';protected static string $view='filament.pages.upbringing-insights';public array $students=[];public array $groups=[];public array $stats=[];
public function mount():void{$p=request()->attributes->get('academic_period');if(!$p)return;$students=DB::table('students as s')->leftJoin('study_groups as g','g.id','=','s.current_group_id')->leftJoin('student_merit_actions as a',function($j)use($p){$j->on('a.student_id','=','s.id')->where('a.academic_period_id',$p->id)->where('a.status','active');})->where('s.status','active')->groupBy('s.id','s.last_name','s.first_name','g.id','g.name')->select('s.id','s.last_name','s.first_name','g.name as group_name',DB::raw('COALESCE(SUM(a.rating_points),0) rating'))->orderByDesc('rating')->get();$this->students=$students->map(fn($x)=>(array)$x)->all();$this->groups=$students->groupBy('group_name')->map(fn($x)=>['name'=>$x->first()->group_name?:'Без группы','students'=>$x->count(),'rating'=>$x->sum('rating')])->sortByDesc('rating')->values()->all();$this->stats=['events'=>DB::table('upbringing_events')->where('academic_period_id',$p->id)->count(),'completed'=>DB::table('upbringing_events')->where('academic_period_id',$p->id)->where('status','completed')->count(),'achievements'=>DB::table('student_achievements')->where('academic_period_id',$p->id)->count(),'open_cases'=>DB::table('student_support_cases')->where('academic_period_id',$p->id)->where('status','!=','closed')->count(),'clubs'=>DB::table('student_clubs')->where('academic_period_id',$p->id)->where('active',1)->count()];}}
